// Construit la page HTML de la file de modération du Comptoir Voyage
const res = $input.first().json;
const q = $('Page modération').first().json.query || {};
const token = q.token || '';
const msg = q.msg || '';

const ACTION_URL = 'https://n8n.gansere.com/webhook/lvpt-moderation-action';

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({
  '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
}[c]));

const COULEURS = {
  vert: '#2f9e6b', ambre: '#c98a12', bleu: '#3b7dd8',
  rose: '#d4537f', teal: '#23918e', rouge: '#d64545'
};

const hidden = (name, value) => `<input type="hidden" name="${name}" value="${esc(value)}">`;

let titrePage = 'Modération';
let contenu = '';

if (!res || res.ok !== true) {
  titrePage = 'Lien invalide';
  contenu = `<div class="vide"><h2>Lien invalide</h2>
    <p>Ouvre la page depuis le bouton « Modérer » d'une notification ntfy.</p></div>`;
} else if (!res.items || res.items.length === 0) {
  contenu = `<div class="vide"><h2>Rien à modérer 🎉</h2>
    <p>Tous les posts du Comptoir Voyage ont été traités.</p></div>`;
} else {
  titrePage = `Modération (${res.items.length})`;
  contenu = res.items.map((p) => {
    const couleur = COULEURS[(p.couleur || '').toLowerCase()] || p.couleur || '#6b7280';
    const lieu = [p.ville, p.pays].filter(Boolean).join(', ');
    const auteur = [p.auteur, p.email ? `(${p.email})` : ''].filter(Boolean).join(' ') || 'Utilisateur inconnu';
    const nbCom = Number(p.nb_commentaires || 0);
    return `
    <article class="post">
      <div class="meta">
        <span class="chip" style="background:${esc(couleur)}">${esc(p.categorie || 'Sans catégorie')}</span>
        <span class="date">${esc(p.date)}</span>
      </div>
      <h2>${esc(p.titre)}</h2>
      ${p.description ? `<p class="desc">${esc(p.description).replace(/\n/g, '<br>')}</p>` : ''}
      <ul class="infos">
        ${lieu ? `<li>📍 ${esc(lieu)}</li>` : ''}
        <li>👤 ${esc(auteur)}</li>
        <li>💬 ${nbCom} commentaire${nbCom > 1 ? 's' : ''}</li>
      </ul>
      <div class="actions">
        <form method="post" action="${ACTION_URL}">
          ${hidden('token', token)}${hidden('id', p.id_post)}${hidden('action', 'valider')}
          <button type="submit" class="btn ok">✓ Valider</button>
        </form>
        <form method="post" action="${ACTION_URL}"
              onsubmit="return confirm('Supprimer définitivement ce post et ses commentaires ?')">
          ${hidden('token', token)}${hidden('id', p.id_post)}${hidden('action', 'supprimer')}
          <button type="submit" class="btn danger">Supprimer</button>
        </form>
      </div>
    </article>`;
  }).join('');
}

const bandeau = msg && res && res.ok === true
  ? `<div class="bandeau ${msg.startsWith('Erreur') ? 'erreur' : ''}">${esc(msg)}</div>`
  : '';

const html = `<!doctype html>
<html lang="fr">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="robots" content="noindex, nofollow">
<title>${esc(titrePage)} · LVPT</title>
<style>
  :root { --coral:#e8664f; --navy:#1e2a3a; --fond:#f5f3ee; --carte:#ffffff; --gris:#6b7280; --vert:#2f9e6b; }
  * { box-sizing:border-box; }
  body { margin:0; background:var(--fond); color:var(--navy);
         font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Arial,sans-serif; }
  header { padding:20px 16px 8px; max-width:720px; margin:0 auto; }
  header h1 { margin:0; font-size:22px; }
  header p { margin:4px 0 0; color:var(--gris); font-size:14px; }
  main { max-width:720px; margin:0 auto; padding:8px 16px 40px; }
  .bandeau { background:#e7f5ee; color:#1d6b47; border-radius:10px; padding:10px 14px; margin-bottom:14px; font-size:14px; }
  .bandeau.erreur { background:#fdeaea; color:#9b2c2c; }
  .post { background:var(--carte); border-radius:14px; padding:16px; margin-bottom:14px;
          box-shadow:0 1px 3px rgba(30,42,58,.08); }
  .meta { display:flex; justify-content:space-between; align-items:center; gap:8px; }
  .chip { color:#fff; font-size:12px; font-weight:600; padding:3px 10px; border-radius:999px; }
  .date { color:var(--gris); font-size:13px; }
  .post h2 { font-size:18px; margin:10px 0 6px; }
  .desc { margin:0 0 10px; line-height:1.5; font-size:15px; white-space:normal; overflow-wrap:anywhere; }
  .infos { list-style:none; padding:0; margin:0 0 14px; color:var(--gris); font-size:13px; }
  .infos li { margin:2px 0; overflow-wrap:anywhere; }
  .actions { display:flex; gap:10px; }
  .actions form { flex:1; margin:0; }
  .btn { width:100%; border:0; border-radius:999px; padding:12px; font-size:15px; font-weight:600; cursor:pointer; }
  .btn.ok { background:var(--vert); color:#fff; }
  .btn.danger { background:#fff; color:#c0392b; border:1.5px solid #e3b4ae; }
  .vide { text-align:center; padding:48px 16px; color:var(--gris); }
  .vide h2 { color:var(--navy); }
</style>
</head>
<body>
<header>
  <h1>Comptoir Voyage — modération</h1>
  <p>Posts des utilisateurs pas encore validés, du plus récent au plus ancien.</p>
</header>
<main>
  ${bandeau}
  ${contenu}
</main>
</body>
</html>`;

return [{ json: { html } }];
